def top_k(lst, k):
    newlst = []
    while len(newlst)<k:
        maximum = lst[0]
        for i in lst:
            if i > maximum:
                maximum = i
        newlst.append(maximum)
        lst.remove(maximum)
    return newlst

def top_k(lst, k):
    #top k in descending order
    sort = []
    x = 0
    while x < k:
        largest = lst[0]
        for element in lst:
            if element > largest:
                largest = element
        lst.remove(largest)
        sort.append(largest)
        x = x + 1
    return sort

